import json,hashlib,math
from pathlib import Path
root=Path.home()/'dojo-data/laptop'
out={'rows':[],'pilots':[],'diagnoses':{},'manifests':{},'admissions':{},'recipes':{}}
for d in root.glob('r2e-panel-*'):
 if not d.is_dir():continue
 for p in d.glob('*_episodes.jsonl'):
  for l in p.read_text().splitlines():out['rows'].append(dict(json.loads(l),run_dir=d.name))
for name in ('std','random'):
 for p in (root/f'r2e-base-{name}').glob('*_episodes.jsonl'):
  out['pilots'].extend({'name':name,'row':json.loads(l)} for l in p.read_text().splitlines())
for prefix in ('r2e-probe','r2e-production','r2e-loadsafe','r2e-wide-probe'):
 for d in root.glob(prefix+'-*'):
  if not d.is_dir():continue
  for p in d.glob('*_episodes.jsonl'):
   out.setdefault('screens',[]).extend({'name':d.name,'row':json.loads(l)} for l in p.read_text().splitlines())
for d in (root/'coverage18').glob('r2e-loadsafe-*'):
 if not d.is_dir():continue
 for p in d.glob('*_episodes.jsonl'):
  out.setdefault('screens',[]).extend({'name':d.name,'bank':'coverage18','row':json.loads(l)} for l in p.read_text().splitlines())
for task in ('store_laptop_and_headphones','store_laptop_and_headphones_random'):
 d=root/'coverage18/simlab/layouts'/task
 ix=d/'settled_index.json'
 if ix.exists():out.setdefault('coverage',{})[task]={'index':json.loads(ix.read_text()),'files':[{'file':p.name,'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'headset_asset':json.loads(p.read_text()).get('Rigid',{}).get('headset',[{}])[0].get('category_idx')} for p in sorted(d.glob('*.settled.json'))]}
raw=list(root.glob('round2e-*.json'))+list((root/'round2e').glob('*/row.json'))+list((root/'round2e').glob('screen-*.json'))+list((root/'round2e').glob('*staging.json'))
for p in raw:
 d=json.loads(p.read_text());meta={'raw_remote':str(p),'sha256':hashlib.sha256(p.read_bytes()).hexdigest()}
 if isinstance(d,dict) and 'trials' in d:
  for t in d['trials']:
   fs=t.pop('frames',[]);t['raw_frame_count']=len(fs)
   if fs:
    T=t['T'];near=min(range(len(fs)),key=lambda i:sum((fs[i]['tcp'][k][3]-T[k][3])**2 for k in range(3)))
    inds=sorted(set([0,near,max(0,len(fs)-31),len(fs)-1]))
    t['keyframes']=[fs[i] for i in inds]
    t['final_pinch_site_error_mm']=math.sqrt(sum(v*v for v in fs[-1]['site_error_mm']))
 meta['data']=d;out['diagnoses'][str(p.relative_to(root))]=meta
for p in (root/'logs').glob('r2e-*.admission'):out['admissions'][p.name]=p.read_text()
for p in [*root.glob('round2e-manifest-*.json'),*root.glob('round2e-loadsafe-manifest-*.json')]:out['manifests'][p.name]=json.loads(p.read_text())
for p in sorted(root.glob('round2e-*.py'))+[root/'job.sh']:
 out['recipes'][p.name]={'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'source':p.read_text()}
print(json.dumps(out))

