import json,numpy as np
from dojo.simlab import paths
from dojo.skills import headset,grasps as G,library as L
from dojo.skills.skills import Skills,SkillResult,PlacePlan
from dojo.skills.geometry import T_from,inv_T
from dojo.skills.kinematics import TABLE_Z
sk.hang_cradle='straddle';sk.headset_seat='on';sk.headset_carry='staged';sk.headset_grasp='cups';sk.headset_table='mesh';sk.headset_stage='off';sk.headset_retry='sites';sk.coll.held_table='mesh'
old_cup=headset.cup_grasps;old_transfer=Skills.plan_transfer;meta={'banks':[],'staging':[]};context={}
def bridge_frame(o):return L.functional_frames(o,'headband_bridge',active=True)[0]
def upright(o):return float((o.T@bridge_frame(o))[2,2])>.95
def bank(sk,o,arm,tag='headband_bridge'):
 if not upright(o):
  gg=old_cup(sk,o,arm,tag)
  for g in gg:g.clear_w=G.MAX_GAP
  return gg
 H=o.T@bridge_frame(o);out=[]
 for xx in (0.,-.025,.025,-.045,.045):
  for dz in (0.,-.004,-.008):
   for tilt in (70.,80.,90.):
    for sign in (-1,1):
     app=H[:3,:3]@np.array([sign*np.sin(np.radians(tilt)),0.,-np.cos(np.radians(tilt))])
     for flip in (-1,1):
      T=T_from(H[:3,3]+H[:3,0]*xx+H[:3,2]*dz,G._frame(app,H[:3,1]*flip))
      w=G.mesh_width_at(o,T,depths=(0.,.004,.008))
      if w is None or not .006<=w<=.06:continue
      out.append(G.Grasp('antipodal',T,w,pre_dist=.05,score=(90-tilt)/900+abs(xx)*10+abs(dz)*10,note=f'bridge x{xx:.3f} dz{dz:.3f} tilt{tilt:.0f}',clear_w=G.MAX_GAP))
 meta['banks'].append({'asset':o.asset.key,'arm':arm,'n':len(out)});print('BRIDGE_BANK',arm,len(out),flush=True);return out
headset.cup_grasps=bank
def transfer(self,label,targets,**kw):
 o=self.world.obj(label)
 if label=='headset' and upright(o):
  kw['max_pick_tilt']=95.
  if any(float((T@bridge_frame(o))[2,3])>context['H'][2,3]+.015 for T in targets):
   targets=[np.array(T).copy() for T in targets]
   for T in targets:T[2,3]+=.02
   kw['place_kw']={**kw.get('place_kw',{}),'pre_h':.01}
 return old_transfer(self,label,targets,**kw)
__import__('dojo.skills.skills',fromlist=['Skills']).Skills.plan_transfer=transfer
def release(To,rel,*,cradle,seat):
 T=To@inv_T(rel)
 if cradle:T[2,3]+=.046
 return T
L.hang_release_target=release

H=L.hook_frames(sk.world.obj('stand'),'support_cradle')[0][1];context['H']=H
o=sk.world.obj('headset');R=(H@inv_T(bridge_frame(o)))[:3,:3]
local=np.array([[0.011166147578088863, 0.8885895143686989, -0.4585673255938154, 0.04664385215888156], [0.9966873376430323, 0.027055605461482085, 0.07669644838685488, -0.002978237912658277], [0.08055847646467267, -0.4579046507375882, -0.8853438104502562, -0.06634292302169587], [0.0, 0.0, 0.0, 1.0]])
g=G.Grasp('antipodal',o.T@local,0.025957706950822182,clear_w=G.MAX_GAP,note='known clean right cup')
p=sk.plan_pick('headset','right',grasps=[g],squeeze=8)
if isinstance(p,SkillResult):
 print('KNOWN_PICK_REFUSE',str(p),flush=True)
else:
 r=sk._record(sk.run_pick(p));print('KNOWN_PICK',str(r),flush=True)
 if r.ok and r.status=='ok':
  for xy in [(0.,-.25),(.05,-.25),(-.05,-.25)]:
   T=L.rest_with_R(sk,'headset',xy,R);o=sk.world.obj('headset');T[2,3]=TABLE_Z+.003-float((np.asarray(o.asset.mesh[0])@R.T)[:,2].min())
   pl=sk.plan_place('right',T,release_gap=.05,pre_h=.03,approach_rad=.03,approach_staged=True,settle=8,open_steps=8)
   if not isinstance(pl,PlacePlan):print('KNOWN_UP_REFUSE',xy,str(pl),flush=True);continue
   rr=sk._record(sk.run_place(pl,tol_xy=.015,tol_tilt=25.,tol_z=.05));print('KNOWN_UP_PLACE',str(rr),flush=True);break
  sk.ex.hold(30,name='known_upright_rest');sk.refresh();o=sk.world.obj('headset');print('KNOWN_UP_POSE',o.T.tolist(),flush=True)
  if upright(o):
   hh=L.hang_on_hooks(sk,['headset'],'stand','support_cradle','headband_bridge');print('KNOWN_BRIDGE_HANG',str(hh),flush=True);sk.ex.hold(30,name='known_support_proof')
sk.finish();sk.ex.hold(10,use_reserve=True);sk.refresh()
out={'history':[vars(x) for x in sk.history],'probe':meta,'score':env.score(),'reward':env.reward(),'final_headset_T':sk.world.obj('headset').T.tolist()}
(paths.DATA/'round2e-known-std48.json').write_text(json.dumps(out,indent=2,default=lambda x:x.tolist() if hasattr(x,'tolist') else str(x)));print('KNOWN_FINAL',out['score'],flush=True)
